// Build date window: last 7 days
const now = new Date();
const since = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const repos = ($env.GITHUB_REPOS || 'anthropics/anthropic-sdk-python').split(',').map(r => r.trim());
const lang  = ($env.SUMMARY_LANGUAGE || 'EN').toUpperCase();

return repos.map(repo => ({
  json: {
    repo,
    since: since.toISOString(),
    until: now.toISOString(),
    language: lang
  }
}));

// ── Aggregate data from all three GitHub nodes ──────────────────────────────
const window = $('Build Date Windows').item.json;
const repo   = window.repo;
const since  = new Date(window.since);
const until  = new Date(window.until);

// Raw arrays from upstream nodes (may be paginated arrays or error objects)
const allCommits = Array.isArray($('Get Commits').item.json)    ? $('Get Commits').item.json    : [];
const allPRs     = Array.isArray($('Get Merged PRs').item.json) ? $('Get Merged PRs').item.json : [];
const allIssues  = Array.isArray($('Get Closed Issues').item.json) ? $('Get Closed Issues').item.json : [];

// Filter PRs merged this week
const mergedPRs = allPRs.filter(pr =>
  pr.merged_at && new Date(pr.merged_at) >= since && new Date(pr.merged_at) <= until
);

// Filter issues closed this week (exclude PRs — GitHub returns PRs as issues too)
const closedIssues = allIssues.filter(issue =>
  !issue.pull_request &&
  issue.closed_at &&
  new Date(issue.closed_at) >= since
);

// ── Team member breakdown ────────────────────────────────────────────────────
const authorStats = {};
for (const commit of allCommits) {
  const login = commit.author?.login || commit.commit?.author?.name || 'unknown';
  if (!authorStats[login]) authorStats[login] = { commits: 0, prs: 0, issues_closed: 0 };
  authorStats[login].commits++;
}
for (const pr of mergedPRs) {
  const login = pr.user?.login || 'unknown';
  if (!authorStats[login]) authorStats[login] = { commits: 0, prs: 0, issues_closed: 0 };
  authorStats[login].prs++;
}
for (const issue of closedIssues) {
  const login = issue.assignee?.login || issue.user?.login || 'unknown';
  if (!authorStats[login]) authorStats[login] = { commits: 0, prs: 0, issues_closed: 0 };
  authorStats[login].issues_closed++;
}

// ── Metrics ──────────────────────────────────────────────────────────────────
const totalAdditions = mergedPRs.reduce((s, pr) => s + (pr.additions || 0), 0);
const totalDeletions = mergedPRs.reduce((s, pr) => s + (pr.deletions || 0), 0);

// Build compact summaries for the Claude prompt
const commitSummary = allCommits.slice(0, 30).map(c =>
  `- [${(c.author?.login || c.commit?.author?.name || '?')}] ${c.commit?.message?.split('\n')[0]}`
).join('\n');

const prSummary = mergedPRs.slice(0, 20).map(pr =>
  `- #${pr.number} by @${pr.user?.login}: ${pr.title}`
).join('\n');

const issueSummary = closedIssues.slice(0, 20).map(i =>
  `- #${i.number}: ${i.title} (closed by @${i.assignee?.login || i.user?.login || '?'})`
).join('\n');

const teamBreakdown = Object.entries(authorStats)
  .sort((a, b) => (b[1].commits + b[1].prs) - (a[1].commits + a[1].prs))
  .map(([user, s]) => `  ${user}: ${s.commits} commits, ${s.prs} PRs merged, ${s.issues_closed} issues closed`)
  .join('\n');

return [{
  json: {
    repo,
    since: window.since,
    until: window.until,
    language: window.language,
    metrics: {
      total_commits:  allCommits.length,
      merged_prs:     mergedPRs.length,
      closed_issues:  closedIssues.length,
      contributors:   Object.keys(authorStats).length,
      lines_added:    totalAdditions,
      lines_removed:  totalDeletions
    },
    teamBreakdown,
    commitSummary,
    prSummary,
    issueSummary
  }
}];

