const claudeResponse = $json;
const content = claudeResponse.content?.[0]?.text || '(no summary generated)';
const aggregated = $('Aggregate & Build Metrics').item.json;

const header = `# 📅 Weekly Dev Summary: \`${aggregated.repo}\`\n` +
  `**Period:** ${aggregated.since.substring(0,10)} → ${aggregated.until.substring(0,10)}\n`;

return [{ json: { fullSummary: header + content, repo: aggregated.repo, metrics: aggregated.metrics } }];
